public class TFMValidationDocumentTypeAttribute  extends SysAttribute implements SysExtensionIAttribute
{
    MethodName			methodName;
    TFMDocumentTypeId	docId;

}

Method.Source:
void new(TFMDocumentTypeId	_docId, MethodName _methodName)
{
    super();

    methodName = _methodName;
    docId = _docId;

}

public MethodName parmMethodName(MethodName	_methodName = methodName)
{
    methodName = _methodName;

    return methodName;
}

public TFMPageID parmDocumentType(TFMDocumentTypeId	_docId = docId)
{
    docId = _docId;

    return docId;
}
